use novel_storage::*;
use serde_json::{Value,json};
use sha2::{Digest,Sha256};
use sqlx::Connection;
fn scene(text:&str)->Scene{Scene{schema_version:1,title:"Arabic branch يس".into(),document:json!({"type":"doc","content":[{"type":"paragraph","attrs":{"dir":"rtl","lang":"ar","lineSpacing":1.5},"content":[{"type":"text","text":text,"marks":[{"type":"bold"},{"type":"underline"}]}]}]})}}
fn bible(sid:&str,note:&str)->Value{json!({"schemaVersion":1,"fields":[],"records":[{"id":"character","kind":"character","name":"محمد","aliases":[],"notes":note,"values":{},"links":[{"kind":"scene","id":sid}]}],"facts":[],"lanes":[{"id":"main","name":"Main","kind":"main"}],"events":[],"boards":[],"constraints":[],"issues":[],"knowledge":[{"id":"known","scope":{"kind":"scenes","sceneIds":[sid]},"factSnapshot":{"subjectId":"character","value":"exact مِ 中文"}}]})}
async fn setup()->(tempfile::TempDir,Storage,Project,SceneRecord){let d=tempfile::tempdir().unwrap();let s=Storage::open(&d.path().join("store.sqlite")).await.unwrap();let p=s.create_project("Main").await.unwrap();let c=s.create_chapter(&p.id,"Chapter").await.unwrap();let a=s.create_scene(&c.id,scene("يس مِ 👩🏽‍🚀 𠀀 \u{e000}")).await.unwrap();s.save_project_data(&p.id,"planning",bible(&a.id,"Original notes"),None).await.unwrap();(d,s,p,a)}
async fn bring(s:&Storage,p:&Project,b:&BranchInfo,piece:&BranchPiece)->Result<Revision,String>{s.bring_back_branch_piece(&p.id,&b.project_id,&b.lineage_revision_id,&piece.branch_entity_id,&piece.entity_type,&piece.branch_head_ids[0],piece.source_head_ids.clone(),piece.branch_head_ids.clone()).await}
#[tokio::test]
async fn exact_branch_history_assets_links_and_unicode_selective_bringback_are_preserved(){
 let(_d,s,p,a)=setup().await;let content=b"synthetic licensed asset".to_vec();s.put_asset(&p.id,ProjectAsset{id:"synthetic-asset".into(),path:"assets/check.txt".into(),mime_type:"text/plain".into(),checksum:format!("{:x}",Sha256::digest(&content)),content:content.clone()}).await.unwrap();
 let b=s.create_project_branch(&p.id,"What if يس").await.unwrap();assert_ne!(b.project_id,p.id);let fork=s.open_project(&b.project_id).await.unwrap();let sc=&fork.scenes[0];assert_eq!(sc.scene,a.scene);assert_ne!(sc.id,a.id);assert_eq!(s.list_assets(&b.project_id).await.unwrap()[0].content,content);assert_eq!(s.history(&sc.id).await.unwrap().len(),s.history(&a.id).await.unwrap().len());let plan=s.load_project_data(&b.project_id,"planning").await.unwrap().unwrap();assert_eq!(plan.payload["records"][0]["links"][0]["id"],sc.id);assert_eq!(plan.payload["knowledge"][0]["scope"]["sceneIds"][0],sc.id);
 let unchanged=s.compare_project_branch(&p.id,&b.project_id,0,30).await.unwrap();assert!(unchanged.pieces.iter().all(|v|!v.differs&&!v.branch_changed&&!v.source_changed));
 let modified=s.save_scene(&sc.id,scene("Branch مِ 中文"),Some(sc.revision_id.clone())).await.unwrap();let main=s.save_scene(&a.id,scene("Newer main"),Some(a.revision_id.clone())).await.unwrap();let plan2=s.save_project_data(&b.project_id,"planning",bible(&sc.id,"What-if bible"),Some(plan.revision_id)).await.unwrap();let cmp=s.compare_project_branch(&p.id,&b.project_id,0,30).await.unwrap();let row=cmp.pieces.iter().find(|v|v.entity_type=="scene").unwrap();assert!(row.branch_changed&&row.source_changed&&row.differs);let result=bring(&s,&p,&b,row).await.unwrap();assert_eq!(result.parents,vec![main.revision_id]);assert_eq!(result.payload,serde_json::to_value(modified.scene).unwrap());assert_ne!(result.id,modified.revision_id);assert_eq!(s.open_project(&p.id).await.unwrap().project.title,"Main");
 let row=cmp.pieces.iter().find(|v|v.entity_type=="projectData").unwrap();let recovered=bring(&s,&p,&b,row).await.unwrap();assert_eq!(recovered.payload["records"][0]["links"][0]["id"],a.id);assert_eq!(recovered.payload["records"][0]["notes"],"What-if bible");assert_eq!(recovered.payload["knowledge"][0]["factSnapshot"],plan2.payload["knowledge"][0]["factSnapshot"]);assert_eq!(s.load_scene(&sc.id).await.unwrap().revision_id,modified.revision_id);
}
#[tokio::test]
async fn source_and_branch_cas_conflicts_deletions_and_unmapped_links_never_overwrite(){
 let(_d,s,p,a)=setup().await;let b=s.create_project_branch(&p.id,"Experiment").await.unwrap();let fork=s.open_project(&b.project_id).await.unwrap();let sc=&fork.scenes[0];let cmp=s.compare_project_branch(&p.id,&b.project_id,0,30).await.unwrap();let row=&cmp.pieces[0];let main=s.save_scene(&a.id,scene("Concurrent main"),Some(a.revision_id.clone())).await.unwrap();assert!(bring(&s,&p,&b,row).await.unwrap_err().starts_with("Conflict"));let current=s.compare_project_branch(&p.id,&b.project_id,0,30).await.unwrap();s.save_scene(&sc.id,scene("Concurrent branch"),Some(sc.revision_id.clone())).await.unwrap();assert!(bring(&s,&p,&b,&current.pieces[0]).await.unwrap_err().starts_with("Conflict"));assert_eq!(s.load_scene(&a.id).await.unwrap().revision_id,main.revision_id);
 s.preserve_conflict(&sc.id,scene("Competing"),&sc.revision_id).await.unwrap();let conflict=s.compare_project_branch(&p.id,&b.project_id,0,30).await.unwrap();assert!(!conflict.pieces[0].can_bring_back);assert!(bring(&s,&p,&b,&conflict.pieces[0]).await.is_err());
 let other=s.create_project_branch(&p.id,"Deleted experiment").await.unwrap();let branch_sc=s.open_project(&other.project_id).await.unwrap().scenes.remove(0);let deletion=s.delete_scene(&branch_sc.id,&branch_sc.revision_id).await.unwrap();let deleted=s.compare_project_branch(&p.id,&other.project_id,0,30).await.unwrap();assert_eq!(deleted.pieces[0].branch_head_ids,vec![deletion]);assert!(!deleted.pieces[0].can_bring_back);assert!(bring(&s,&p,&other,&deleted.pieces[0]).await.is_err());
 let revived=s.create_project_branch(&p.id,"Revival").await.unwrap();let deletion=s.delete_scene(&a.id,&main.revision_id).await.unwrap();let cmp=s.compare_project_branch(&p.id,&revived.project_id,0,30).await.unwrap();let restored=bring(&s,&p,&revived,&cmp.pieces[0]).await.unwrap();assert_eq!(restored.parents,vec![deletion]);assert!(s.load_project_scene(&p.id,&a.id).await.is_ok());
 let project=s.open_project(&revived.project_id).await.unwrap();let new=s.create_scene(&project.chapters[0].id,scene("New branch scene")).await.unwrap();let old=s.load_project_data(&revived.project_id,"planning").await.unwrap().unwrap();s.save_project_data(&revived.project_id,"planning",bible(&new.id,"Unmapped"),Some(old.revision_id)).await.unwrap();let cmp=s.compare_project_branch(&p.id,&revived.project_id,0,30).await.unwrap();assert!(cmp.pieces.iter().any(|p|p.source_entity_id.is_none()&&!p.can_bring_back));let plan=cmp.pieces.iter().find(|p|p.entity_type=="projectData").unwrap();assert!(bring(&s,&p,&revived,plan).await.unwrap_err().contains("scene"));
}
#[tokio::test]
async fn lineage_archive_reimport_nested_forks_sync_and_bounded_pages(){
 let(_d,s,p,a)=setup().await;let b=s.create_project_branch(&p.id,"Branch").await.unwrap();let imported=s.import_archive(&s.export_archive(&b.project_id).await.unwrap()).await.unwrap();let list=s.list_project_branches(&p.id).await.unwrap();assert_eq!(list.len(),2);let cmp=s.compare_project_branch(&p.id,&imported.project.id,0,1).await.unwrap();assert_eq!(cmp.total,2);assert!(cmp.has_more);assert!(!cmp.pieces[0].differs);assert_eq!(cmp.pieces[0].source_entity_id.as_deref(),Some(a.id.as_str()));assert!(s.compare_project_branch(&p.id,&b.project_id,0,101).await.is_err());assert_eq!(s.compare_project_branch(&p.id,&b.project_id,1,1).await.unwrap().pieces[0].entity_type,"projectData");
 let nested=s.create_project_branch(&b.project_id,"Nested").await.unwrap();assert_eq!(nested.source_project_id,b.project_id);let data=s.load_project_data(&nested.project_id,"branchLineage").await.unwrap().unwrap();assert_eq!(data.payload["origins"].as_array().unwrap().len(),2);assert!(s.compare_project_branch(&p.id,&nested.project_id,0,30).await.is_err());assert!(s.compare_project_branch(&b.project_id,&nested.project_id,0,30).await.is_ok());assert!(s.save_project_data(&b.project_id,"branchLineage",data.payload,None).await.is_err());
 let replica_dir=tempfile::tempdir().unwrap();let replica=Storage::open(&replica_dir.path().join("replica.sqlite")).await.unwrap();for pid in [&p.id,&b.project_id]{let epoch=s.sync_cursor().await.unwrap().epoch;let local=replica.sync_cursor().await.unwrap().epoch;let page=s.pull_revisions(pid,SyncCursor{epoch:epoch.clone(),sequence:0},100).await.unwrap();replica.ingest_revisions(pid,&local,&epoch,s.sync_manifest(pid).await.unwrap(),page.revisions).await.unwrap();}assert!(replica.compare_project_branch(&p.id,&b.project_id,0,30).await.unwrap().pieces.iter().all(|p|!p.differs));
}
#[tokio::test]
async fn foreign_revisions_corrupt_checksums_and_failed_branch_transactions_are_rejected(){
 let(d,s,p,a)=setup().await;let b=s.create_project_branch(&p.id,"Branch").await.unwrap();let cmp=s.compare_project_branch(&p.id,&b.project_id,0,30).await.unwrap();let row=&cmp.pieces[0];assert!(s.bring_back_branch_piece(&p.id,&b.project_id,&b.lineage_revision_id,&row.branch_entity_id,"scene",&a.revision_id,row.source_head_ids.clone(),row.branch_head_ids.clone()).await.is_err());assert!(s.bring_back_branch_piece(&p.id,&b.project_id,"wrong-lineage",&row.branch_entity_id,"scene",&row.branch_head_ids[0],row.source_head_ids.clone(),row.branch_head_ids.clone()).await.is_err());
 let mut raw=sqlx::SqliteConnection::connect_with(&sqlx::sqlite::SqliteConnectOptions::new().filename(d.path().join("store.sqlite"))).await.unwrap();let count=s.list_projects().await.unwrap().len();sqlx::query("CREATE TRIGGER fail_branch BEFORE INSERT ON revision_envelope WHEN NEW.operation='branchLineage' BEGIN SELECT RAISE(ABORT,'synthetic fault'); END").execute(&mut raw).await.unwrap();assert!(s.create_project_branch(&p.id,"Failed branch").await.is_err());assert_eq!(s.list_projects().await.unwrap().len(),count);sqlx::query("DROP TRIGGER fail_branch").execute(&mut raw).await.unwrap();sqlx::query("DROP TRIGGER immutable_revision_update").execute(&mut raw).await.unwrap();sqlx::query("UPDATE revision_envelope SET checksum='corrupt' WHERE id=?").bind(&row.source_head_ids[0]).execute(&mut raw).await.unwrap();assert!(bring(&s,&p,&b,row).await.unwrap_err().contains("checksum"));assert_eq!(s.load_project_scene(&b.project_id,&row.branch_entity_id).await.unwrap().revision_id,row.branch_head_ids[0]);
}
fn alternatives(a:&SceneRecord)->Value{let block=a.scene.document["content"][0].clone();json!({"schemaVersion":1,"scenes":[{"sceneId":a.id,"groups":[{"id":"group","label":"Choice","anchor":{"blockIndex":0,"documentHash":"a".repeat(64),"block":block},"sceneRevisionId":a.revision_id,"originalId":"original","activeId":"original","versions":[{"id":"original","label":"Original","block":block}]}]}]})}
#[tokio::test]
async fn alternatives_require_owned_saved_sources_keep_versions_and_remap_archives(){
 let(_d,s,p,a)=setup().await;let value=alternatives(&a);let saved=s.save_project_data(&p.id,"paragraphAlternatives",value.clone(),None).await.unwrap();let mut corrupted=value.clone();corrupted["scenes"][0]["groups"][0]["versions"][0]["block"]["content"][0]["text"]=json!("Overwrite original");assert!(s.save_project_data(&p.id,"paragraphAlternatives",corrupted,Some(saved.revision_id.clone())).await.unwrap_err().contains("immutable"));let changed=s.save_scene(&a.id,scene("Saved choice"),Some(a.revision_id.clone())).await.unwrap();let mut next=value.clone();next["scenes"][0]["groups"][0]["sceneRevisionId"]=json!(changed.revision_id);let saved=s.save_project_data(&p.id,"paragraphAlternatives",next.clone(),Some(saved.revision_id)).await.unwrap();let foreign=s.create_project("Foreign").await.unwrap();let c=s.create_chapter(&foreign.id,"Foreign").await.unwrap();let fs=s.create_scene(&c.id,scene("Foreign")).await.unwrap();let mut wrong=next.clone();wrong["scenes"][0]["groups"][0]["sceneRevisionId"]=json!(fs.revision_id);assert!(s.save_project_data(&p.id,"paragraphAlternatives",wrong,Some(saved.revision_id)).await.unwrap_err().contains("belong"));
 let imported=s.import_archive(&s.export_archive(&p.id).await.unwrap()).await.unwrap();let copied=s.load_project_data(&imported.project.id,"paragraphAlternatives").await.unwrap().unwrap().payload;assert_eq!(copied["scenes"][0]["sceneId"],imported.scenes[0].id);assert_eq!(copied["scenes"][0]["groups"][0]["sceneRevisionId"],imported.scenes[0].revision_id);assert_eq!(copied["scenes"][0]["groups"][0]["versions"],value["scenes"][0]["groups"][0]["versions"]);
}
#[tokio::test]
async fn whole_bible_compare_cas_absence_and_stale_source_or_branch_are_atomic(){
 let(_d,s,p,_a)=setup().await;let b=s.create_project_branch(&p.id,"Bible experiment").await.unwrap();let compared=s.compare_project_branch(&p.id,&b.project_id,0,30).await.unwrap();let row=compared.pieces.iter().find(|r|r.entity_type=="projectData").unwrap();let old=s.load_project_data(&p.id,"planning").await.unwrap().unwrap();let mut payload=old.payload;payload["records"][0]["notes"]=json!("New source notes");let fresh=s.save_project_data(&p.id,"planning",payload,Some(old.revision_id)).await.unwrap();assert!(bring(&s,&p,&b,row).await.unwrap_err().starts_with("Conflict"));let compared=s.compare_project_branch(&p.id,&b.project_id,0,30).await.unwrap();let row=compared.pieces.iter().find(|r|r.entity_type=="projectData").unwrap();let old=s.load_project_data(&b.project_id,"planning").await.unwrap().unwrap();let mut payload=old.payload;payload["records"][0]["notes"]=json!("New branch notes");s.save_project_data(&b.project_id,"planning",payload,Some(old.revision_id)).await.unwrap();assert!(bring(&s,&p,&b,row).await.unwrap_err().starts_with("Conflict"));assert_eq!(s.load_project_data(&p.id,"planning").await.unwrap().unwrap().revision_id,fresh.revision_id);
 let empty=s.create_project("No bible yet").await.unwrap();let c=s.create_chapter(&empty.id,"Chapter").await.unwrap();let a=s.create_scene(&c.id,scene("First draft")).await.unwrap();let branch=s.create_project_branch(&empty.id,"Invent bible").await.unwrap();let sc=s.open_project(&branch.project_id).await.unwrap().scenes.remove(0);s.save_project_data(&branch.project_id,"planning",bible(&sc.id,"Invented canon"),None).await.unwrap();let compared=s.compare_project_branch(&empty.id,&branch.project_id,0,30).await.unwrap();let row=compared.pieces.iter().find(|r|r.entity_type=="projectData").unwrap();assert!(row.source_head_ids.is_empty()&&row.can_bring_back);let saved=bring(&s,&empty,&branch,row).await.unwrap();assert!(saved.parents.is_empty());assert_eq!(saved.payload["records"][0]["links"][0]["id"],a.id);assert!(bring(&s,&empty,&branch,row).await.unwrap_err().starts_with("Conflict"));
}
#[tokio::test]
async fn invalid_alternative_source_sync_page_rolls_back_receipts_and_revisions(){
 let(_d,s,p,a)=setup().await;let before=s.sync_cursor().await.unwrap();s.save_project_data(&p.id,"paragraphAlternatives",alternatives(&a),None).await.unwrap();let d=tempfile::tempdir().unwrap();let replica=Storage::open(&d.path().join("replica.sqlite")).await.unwrap();let local=replica.sync_cursor().await.unwrap().epoch;replica.ingest_revisions(&p.id,&local,&before.epoch,s.sync_manifest(&p.id).await.unwrap(),s.pull_revisions(&p.id,SyncCursor{epoch:before.epoch.clone(),sequence:0},100).await.unwrap().revisions.into_iter().filter(|r|r.operation!="paragraphAlternatives").collect()).await.unwrap();let mut incoming=s.pull_revisions(&p.id,SyncCursor{epoch:before.epoch.clone(),sequence:before.sequence},100).await.unwrap().revisions;incoming[0].payload["scenes"][0]["groups"][0]["sceneRevisionId"]=json!("missing-source");incoming[0].checksum=format!("{:x}",Sha256::digest(serde_json::to_string(&incoming[0].payload).unwrap().as_bytes()));let cursor=replica.sync_cursor().await.unwrap();let receipts=replica.sync_receipt_count(&p.id,&before.epoch).await.unwrap();assert!(replica.ingest_revisions(&p.id,&local,&before.epoch,s.sync_manifest(&p.id).await.unwrap(),incoming).await.unwrap_err().contains("belong"));assert_eq!(replica.sync_cursor().await.unwrap(),cursor);assert_eq!(replica.sync_receipt_count(&p.id,&before.epoch).await.unwrap(),receipts);assert!(replica.load_project_data(&p.id,"paragraphAlternatives").await.unwrap().is_none());
}
